function drawNoctowlMysticOwl(ctx, cx, cy, scale, t, blink = false) {
  ctx.save();
  ctx.translate(cx, cy);
  ctx.scale(scale, scale);

  const breathPhase = t * 2.1;
  const breathSin = Math.sin(breathPhase);
  const sY = 1.0 + 0.04 * breathSin;
  const sX = 1.0 - 0.02 * breathSin;
  const by = -Math.abs(breathSin) * 2.8;

  // 1. Bóng sàn
  ctx.fillStyle = '#1e293b';
  ctx.beginPath(); ctx.ellipse(0, 42, 26 * (1.0 - 0.15 * breathSin), 6, 0, 0, Math.PI * 2); ctx.fill();

  // 2. Chân
  ctx.fillStyle = '#e2e8f0';
  ctx.beginPath(); ctx.roundRect(-12, by + 28, 6, 12, 2); ctx.fill();
  ctx.beginPath(); ctx.roundRect(6,   by + 28, 6, 12, 2); ctx.fill();

  // 3. Thân & Ngực
  ctx.fillStyle = '#9a3412';
  ctx.beginPath(); ctx.ellipse(0, by + 12, 18 * sX, 18 * sY, 0, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#d4d4d8';
  ctx.beginPath(); ctx.ellipse(0, by + 14, 14 * sX, 14 * sY, 0, 0, Math.PI * 2); ctx.fill();

  // 4. Tam giác ngực
  ctx.fillStyle = '#451a03';
  ctx.beginPath(); ctx.moveTo(-8, by + 8); ctx.lineTo(-4, by + 14); ctx.lineTo(0,  by + 8); ctx.fill();
  ctx.beginPath(); ctx.moveTo(0,  by + 8); ctx.lineTo(4,  by + 14); ctx.lineTo(8,  by + 8); ctx.fill();
  ctx.beginPath(); ctx.moveTo(-4, by + 16); ctx.lineTo(0, by + 22); ctx.lineTo(4,  by + 16); ctx.fill();

  // 5. Cánh
  ctx.fillStyle = '#9a3412';
  ctx.beginPath(); ctx.roundRect(-20, by + 4, 6, 20, 3); ctx.fill();
  ctx.beginPath(); ctx.roundRect(14,  by + 4, 6, 20, 3); ctx.fill();

  // 6. Đầu
  ctx.beginPath(); ctx.arc(0, by - 8, 16 * sX, 0, Math.PI * 2); ctx.fill();

  // 7. Lông mày sừng vàng
  ctx.fillStyle = '#facc15';
  ctx.beginPath();
  ctx.moveTo(-18, by - 16); ctx.lineTo(-22, by - 38); ctx.lineTo(-12, by - 14);
  ctx.lineTo(0,   by - 26);
  ctx.lineTo(12,  by - 14); ctx.lineTo(22,  by - 38); ctx.lineTo(18,  by - 16);
  ctx.fill();

  // 8. Mắt
  ctx.fillStyle = '#1e293b';
  ctx.beginPath(); ctx.arc(-8, by - 8, 6, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(8,  by - 8, 6, 0, Math.PI * 2); ctx.fill();
  if (!blink) {
    ctx.fillStyle = '#ef4444';
    ctx.beginPath(); ctx.arc(-8, by - 8, 4, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(8,  by - 8, 4, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#ffffff';
    ctx.beginPath(); ctx.arc(-9, by - 10, 1.2, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(7,  by - 10, 1.2, 0, Math.PI * 2); ctx.fill();
  }

  // 9. Mỏ
  ctx.fillStyle = '#e2e8f0';
  ctx.beginPath(); ctx.moveTo(-3, by - 6); ctx.lineTo(0, by - 1); ctx.lineTo(3, by - 6); ctx.fill();

  ctx.restore();
}
